typedef unsigned char u_char;
typedef unsigned int u_int;

struct nglFileBuf
{
  u_char *Buf;
  u_int Size;
  u_int UserData;
};

bool KSReadFile(const char *, nglFileBuf *, u_int);
void KSReleaseFile(nglFileBuf *);
char *strchr(const char *, int);
int sscanf(const char *, const char *, ...);
int strcmp(const char *, const char *);

typedef struct SurferDataStruct
{
  int start_stand;
  int start_turn;
  int start_carve;
  int start_anims;
  int end_anims;
  int trickBook[70];
  int learnedtrickBook[16];
  char name[32];
  char name_ps[32];
  char stashfile[16];
  char firstname[32];
  char lastname[32];
  char fullname[32];
  char abbr[4];
  int goofy;
  int load_in_fe;
  int bio_length;
  int has_movie;
  int attr_spin;
  int attr_speed;
  int attr_balance;
  int attr_air;
  char board_ent_name[20];
  char p_board_name[20];
  int selectable;
  int competitor;
  int initially_unlocked;
  char surfer_nick[20];
  int sort_order;
} SurferData;

extern SurferData SurferDataArray[];

#define assert(exp) ((void)0)
#define verify(a) if (a) {}
#define NULL 0

void SURFERDATA_Load(void)
{
    nglFileBuf F;
    KSReadFile("surferdata.dat", &F, 1);
    char *s = (char *) F.Buf;
    const char *format = "%[^,], %[^,], %[^,], %[^,], %[^,], %[^,], %[^,], %d, %d, %d, %d, %d, %d, %d, %d, %[^,], %[^,], %d, %d, %d, %[^,], %d, ";
    for (int i = 0; i < 14; ++i)
    {
         char *p = strchr (s, '\n');
         if (p) *p = 0;
         int n = sscanf(s, format,
              &SurferDataArray[i].name,
              &SurferDataArray[i].name_ps,
              &SurferDataArray[i].stashfile,
              &SurferDataArray[i].firstname,
              &SurferDataArray[i].lastname,
              &SurferDataArray[i].fullname,
              &SurferDataArray[i].abbr,
              &SurferDataArray[i].goofy,
              &SurferDataArray[i].load_in_fe,
              &SurferDataArray[i].bio_length,
              &SurferDataArray[i].has_movie,
              &SurferDataArray[i].attr_spin,
              &SurferDataArray[i].attr_speed,
              &SurferDataArray[i].attr_balance,
              &SurferDataArray[i].attr_air,
              &SurferDataArray[i].board_ent_name,
              &SurferDataArray[i].p_board_name,
              &SurferDataArray[i].selectable,
              &SurferDataArray[i].competitor,
              &SurferDataArray[i].initially_unlocked,
              &SurferDataArray[i].surfer_nick,
              &SurferDataArray[i].sort_order
         );
         if (strcmp(SurferDataArray[i].lastname, "-")==0) SurferDataArray[i].lastname[0] = '\0';
         if (p) *p = '\n';
         assert(22 == n);
         verify((s = strchr(s, '\n')) != NULL);
         ++s;
    }
    KSReleaseFile(&F);
}
